    'pax.one': '{who} disembarks.{fare}', 'pax.many': '{who} disembark.{fare}', 'pax.fare': ' Fare received: {fare} cr{trip}.', 'pax.trip': ' ({change} for the trip)',
    'walkoff': '{name} has had enough of you and your ship, and walks off at {planet}.', 'lapsed': 'Mission failed (deadline passed): {title}',
    'burn.nodest': 'No destination. Press M to open the system map.', 'burn.fuel': 'Not enough reaction mass (need {need}). Refuel or pick a closer destination.',
